import os
import time

STARTED = time.time()


def handler(req, ctx):
    """Answer 200 for as long as this instance is able to."""
    return {
        "statusCode": 200,
        "body": {
            "ok": True,
            "uptime_s": round(time.time() - STARTED, 1),
            "function": os.environ.get("CUBICLE_FUNCTION", ""),
        },
    }
